import{_ as i,C as c,o as l,c as n,al as a,E as o,j as e,a as r}from"./chunks/framework.D1FqHTxE.js";const f=JSON.parse('{"title":"Virtualizer 虚拟滚动","description":"","frontmatter":{},"headers":[],"relativePath":"components/virtualizer.md","filePath":"components/virtualizer.md","lastUpdated":1790593541000}'),h={name:"components/virtualizer.md"};function s(u,t,b,p,m,x){const d=c("XhDemo");return l(),n("div",null,[t[0]||(t[0]=a('<h1 id="virtualizer-虚拟滚动" tabindex="-1">Virtualizer 虚拟滚动 <a class="header-anchor" href="#virtualizer-虚拟滚动" aria-label="Permalink to &quot;Virtualizer 虚拟滚动&quot;">​</a></h1><p>只渲染窗口内的条目，列表再长也只绘制可见的几十条。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/virtualizer" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/virtualizer.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/virtualizer" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/virtualizer" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/virtualizer.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一万条只渲染可视区内的几条，root 要有确定高度，条目的主轴尺寸由作者按 estimateSize 自行编写</p>',5)),o(d,{src:"virtualizer/01-basic"}),t[1]||(t[1]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;virtualizer&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>content</code></strong> · <code>item</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="动态高度" tabindex="-1">动态高度 <a class="header-anchor" href="#动态高度" aria-label="Permalink to &quot;动态高度&quot;">​</a></h3><p>条目开启 measure 后把真实尺寸回传给内核，estimateSize 只是首帧的起点，滚动一遍后即收敛</p>',6)),o(d,{src:"virtualizer/02-dynamic"}),t[2]||(t[2]=e("h3",{id:"滚动到指定条目",tabindex:"-1"},[r("滚动到指定条目 "),e("a",{class:"header-anchor",href:"#滚动到指定条目","aria-label":'Permalink to "滚动到指定条目"'},"​")],-1)),t[3]||(t[3]=e("p",null,"scrollToIndex 按 align 落位：start 贴上沿、center 居中、end 贴下沿，越界下标由内核夹取",-1)),o(d,{src:"virtualizer/03-scroll-to"}),t[4]||(t[4]=e("h3",{id:"横向列表",tabindex:"-1"},[r("横向列表 "),e("a",{class:"header-anchor",href:"#横向列表","aria-label":'Permalink to "横向列表"'},"​")],-1)),t[5]||(t[5]=e("p",null,"horizontal 把主轴换为行内轴：位移改写进行首侧，条目宽度由作者编写，gap 由内核直接计入位移",-1)),o(d,{src:"virtualizer/04-horizontal"}),t[6]||(t[6]=e("h3",{id:"挂载自绘滚动条",tabindex:"-1"},[r("挂载自绘滚动条 "),e("a",{class:"header-anchor",href:"#挂载自绘滚动条","aria-label":'Permalink to "挂载自绘滚动条"'},"​")],-1)),t[7]||(t[7]=e("p",null,"滚动容器是视口，提供一个 id 交给滚动条即可；虚拟滚动只管理渲染哪几条，滚动条只负责绘制滚动位置",-1)),o(d,{src:"virtualizer/05-scrollbar"}),t[8]||(t[8]=e("h3",{id:"与无限滚动组成一条长列表",tabindex:"-1"},[r("与无限滚动组成一条长列表 "),e("a",{class:"header-anchor",href:"#与无限滚动组成一条长列表","aria-label":'Permalink to "与无限滚动组成一条长列表"'},"​")],-1)),t[9]||(t[9]=e("p",null,"哨兵放置在内容层之后而不是条目之间：窗口外的条目根本没有渲染，放在其中的哨兵永远无法进入可视区",-1)),o(d,{src:"virtualizer/06-composed"}),t[10]||(t[10]=e("h3",{id:"随整页滚动",tabindex:"-1"},[r("随整页滚动 "),e("a",{class:"header-anchor",href:"#随整页滚动","aria-label":'Permalink to "随整页滚动"'},"​")],-1)),t[11]||(t[11]=e("p",null,"scrollContainer 设为 window：列表铺在页面里，不另开滚动框，列表上方的内容不必再算 scrollMargin",-1)),o(d,{src:"virtualizer/07-window"}),t[12]||(t[12]=e("h3",{id:"聊天流",tabindex:"-1"},[r("聊天流 "),e("a",{class:"header-anchor",href:"#聊天流","aria-label":'Permalink to "聊天流"'},"​")],-1)),t[13]||(t[13]=e("p",null,"anchor 设为 end：从最新一条看起，贴底时新消息继续贴底；往前翻出历史时，给了 getItemKey 视口不跳",-1)),o(d,{src:"virtualizer/08-chat"}),t[14]||(t[14]=e("h3",{id:"分组标题",tabindex:"-1"},[r("分组标题 "),e("a",{class:"header-anchor",href:"#分组标题","aria-label":'Permalink to "分组标题"'},"​")],-1)),t[15]||(t[15]=e("p",null,"stickyIndices 登记标题的下标：滚过它之后它钉在起点，下一组的标题滚上来时接替",-1)),o(d,{src:"virtualizer/09-sticky"}),t[16]||(t[16]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>条目上千甚至上万。</li><li>首屏卡顿的根源是 DOM 节点太多。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>条目只有几十上百条时，虚拟化带来的复杂度不值得。</li><li>需要浏览器的页内查找命中所有条目时，未渲染的条目无法被搜索。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>支持动态高度（测量而非估算）、横向列表与多列。</li><li><code>overscan</code> 决定窗口外多渲染的条数，滚动时不露白。</li><li>可以滚到指定条目。</li><li>滚动容器由 <code>scrollContainer</code> 决定：缺省 <code>viewport</code> 是视口自己滚；<code>window</code> 是列表铺在页面里、随整页滚动，视口不再是滚动框也不占 Tab 位，列表在页面里的起点由内核现量（每次滚动都重量，页头折叠、上方内容加载完都跟得上），不必再算 <code>scrollMargin</code>。</li><li>条目增删时视口不跳：缺省（<code>anchor</code> 为 <code>start</code>）把视口里第一条按身份放回原处，往前插入条目（向上翻出历史）时它仍停在原来的位置。身份来自 <code>getItemKey</code>，没给时身份就是下标，往前插入只保住下标、内容会整体后移。</li><li><code>anchor</code> 为 <code>end</code> 时从最新一条看起：滚到底后内容再长（追加条目、条目长高）也继续贴底；用户往上翻离开底部就不再拽回，翻回底部重新贴底。列表不足一屏时条目贴着底部排。适合聊天与日志。</li><li><code>stickyIndices</code> 登记要钉在视口起点的条目（分组标题）：滚过它之后它一直钉着，直到下一个登记过的条目接替；它的条目外壳带 <code>data-fixed</code>，按 <code>position: sticky</code> 留在文档流里，自带实底 <code>--xh-virtualizer-sticky-bg</code>。钉住的标题读屏照常读到，不另建一份。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li><code>collectionVirtualizer</code> 是正式集合接线口：<a href="./tree">树</a>、<a href="./listbox">列表框</a>、<a href="./select">选择器</a>、<a href="./combobox">组合框</a>、<a href="./transfer">穿梭框</a>与<a href="./table">表格</a>把完整 collection 交给各自状态机，只用 <code>virtualItems</code> 裁剪 DOM。表格按可见数据行计数，每个虚拟条目装一行数据行。<a href="./log">日志</a>接上它之后，粘底改跟 Virtualizer 的视口与内容层（<code>getViewportElement</code> / <code>getContentElement</code>）走。</li><li>集合接线时 <code>count</code> 必须等于当前语义序列长度；不一致会明确抛错，避免方向键与可见窗口指向两份数据。</li><li>集合自身已有焦点模型，把 <code>viewportTabIndex</code> 设为 <code>-1</code>，不要让虚拟视口额外占一个 Tab 位。</li><li>与<a href="./infinite-scroll">无限滚动</a>组合为边滚边取的长列表：哨兵放在内容层之后，取数目标指向视口层。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>条目高度差异大时使用动态高度模式，不依赖估值。</li><li>条目会增删的列表（消息、动态流）一律给 <code>getItemKey</code>：实测尺寸、视口钉住与节点复用都按它认条目。</li><li>提供滚动到指定条目的入口，否则用户无法找回之前的位置。</li><li>Web Components 跨嵌套宿主组合时，语义条目根用 <code>data-xh-part-owner</code> 声明归属；Virtualizer 外壳仍归 <code>virtualizer</code>，两台宿主不会争写同一节点。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>在虚拟列表内放高度会突变的内容（图片未预留宽高比），滚动时位置跳动。</li><li>依赖 Ctrl + F 查找。</li><li>把<a href="./infinite-scroll">无限滚动</a>的哨兵放进条目之间：窗口外的条目不渲染，哨兵也不渲染，第二页无法获取。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-virtualizer&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhVirtualizerContent</code> <code>XhVirtualizerItem</code> <code>XhVirtualizerRoot</code> <code>XhVirtualizerViewport</code></td></tr><tr><td>组合式函数</td><td><code>useVirtualizer</code></td></tr><tr><td>状态机</td><td><code>virtualizerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/virtualizer.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>总条数，默认 0。</td></tr><tr><td><code>estimateSize</code></td><td><code>number | ((index: number) =&gt; number)</code></td><td></td><td>每条的估算主轴尺寸（px）。等高列表可以直接提供一个数字。 未提供时按 0 计算：所有条目都会落进窗口，先渲染出来再依靠 measureElement 回填真实尺寸。</td></tr><tr><td><code>overscan</code></td><td><code>number</code></td><td></td><td>可视区前后各多渲染的条数，默认 5。</td></tr><tr><td><code>horizontal</code></td><td><code>boolean</code></td><td></td><td>横向列表（主轴是行内轴），默认 false。</td></tr><tr><td><code>gap</code></td><td><code>number</code></td><td></td><td>相邻两条之间的主轴间距（px），默认 0。位移由内核直接计算，不依靠外边距。</td></tr><tr><td><code>getItemKey</code></td><td><code>(index: number) =&gt; string | number</code></td><td></td><td>条目身份。默认即下标；列表会增删时提供稳定 key，测量缓存才能跟随条目。</td></tr><tr><td><code>onRangeChange</code></td><td><code>(details: VirtualizerRangeChangeDetails) =&gt; void</code></td><td></td><td>应渲染的区间变化。只在快照实际变化时回调，滚动但可见区间未变不会触发。</td></tr><tr><td><code>scrollMargin</code></td><td><code>number</code></td><td></td><td>列表起点距滚动容器起点的距离（px），默认 0。 列表上方还有其他内容（页头、筛选栏）时提供它，否则区间会整体偏移该段距离。</td></tr><tr><td><code>paddingStart</code></td><td><code>number</code></td><td></td><td>列表前后的内边距（px），默认 0。计入总长，第一条从 paddingStart 处起算。</td></tr><tr><td><code>paddingEnd</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>lanes</code></td><td><code>number</code></td><td></td><td>多列网格的列数，默认 1（单列）。条目按下标轮流落到各列上。</td></tr><tr><td><code>viewportTabIndex</code></td><td><code>number</code></td><td></td><td>viewport 的 Tab 位；独立列表默认 0，组合进有自身焦点模型的集合时设为 -1。window 形态下视口不滚动，不占 Tab 位。</td></tr><tr><td><code>scrollContainer</code></td><td><code>VirtualizerScrollContainer</code></td><td></td><td>滚动容器：viewport（缺省）是视口节点自己滚；window 是列表铺在页面里、随整页滚动， 列表在页面里的起点由内核现量，不必再给 scrollMargin。</td></tr><tr><td><code>anchor</code></td><td><code>VirtualizerAnchor</code></td><td></td><td>条目增删时钉住哪一头。start（缺省）把视口里第一条按身份放回原处：往前插入条目（向上翻出历史）视口不跳， 需要 getItemKey 给出稳定身份。end 另外从底部看起、已经滚到底时内容再长也继续贴底（聊天流）， 列表不足一屏时条目贴着底部排。</td></tr><tr><td><code>stickyIndices</code></td><td><code>number[]</code></td><td></td><td>钉在视口起点的条目下标（分组标题）：滚过它之后它一直钉着，直到下一个钉住的条目接替。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>range-change</code></td><td><code>VirtualizerRangeChangeDetails</code></td><td>应渲染的区间变化；detail 为 <code>{ virtualItems, totalSize, startIndex, endIndex }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhVirtualizerRoot</code></td><td><code>default</code></td><td><code>VirtualizerRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhVirtualizerItem</code></td><td><code>value</code></td><td><code>number | string</code></td><td>是</td><td>该节点的下标。</td></tr><tr><td><code>XhVirtualizerItem</code></td><td><code>measure</code></td><td><code>boolean</code></td><td></td><td>是否把真实尺寸回传给内核；未开启时条目尺寸按 estimateSize 计算。</td></tr><tr><td><code>XhVirtualizerRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;VirtualizerRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code> · <code>scrolling</code></p><p><strong>事件</strong>：<code>SCROLL.START</code> · <code>SCROLL.END</code> · <code>MEASURE</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>virtualItems</code></td><td><code>readonly VirtualizerItemState[]</code></td><td>当前应渲染的下标，以及它们的位移与尺寸。</td></tr><tr><td><code>totalSize</code></td><td><code>number</code></td><td>整份列表的主轴总长（px）。</td></tr><tr><td><code>startIndex</code></td><td><code>number | null</code></td><td>可视区首条下标（不含过扫描）；没有任何条目可容纳时为 null。</td></tr><tr><td><code>endIndex</code></td><td><code>number | null</code></td><td>可视区末条下标（不含过扫描）；没有任何条目可容纳时为 null。</td></tr><tr><td><code>horizontal</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>lanes</code></td><td><code>number</code></td><td></td></tr><tr><td><code>scrolling</code></td><td><code>boolean</code></td><td>正在滚动。</td></tr><tr><td><code>collectionVirtualizer</code></td><td><code>CollectionVirtualizer</code></td><td>交给集合组件的正式虚拟化桥。</td></tr><tr><td><code>scrollToIndex</code></td><td><code>(index: number, options?: VirtualizerScrollToOptions) =&gt; void</code></td><td>滚动到某一条。越界下标由内核夹取。</td></tr><tr><td><code>measureElement</code></td><td><code>(element: HTMLElement | null) =&gt; void</code></td><td>把条目节点的真实尺寸回填给内核（动态高度使用）。传 null 无副作用。</td></tr><tr><td><code>measure</code></td><td><code>() =&gt; void</code></td><td>丢弃全部实测尺寸重新按估算值排列。视口更换排版时使用。</td></tr><tr><td><code>registerItemElement</code></td><td><code>(index: number, element: HTMLElement | null) =&gt; void</code></td><td>适配器在条目 ref 挂载 / 卸载时登记；业务作者通常不直接调用。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: VirtualizerItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/virtualizer.css</code> 使用 <code>[data-scope=&quot;virtualizer&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>root</code></td><td><code>data-scrolling</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-anchor</code></td><td>&#39;end&#39; | undefined</td></tr><tr><td><code>viewport</code></td><td><code>data-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>viewport</code></td><td><code>data-scroll-container</code></td><td>&#39;window&#39; | undefined</td></tr><tr><td><code>content</code></td><td><code>data-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>item</code></td><td><code>data-fixed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-index</code></td><td>props.index</td></tr><tr><td><code>item</code></td><td><code>data-lane</code></td><td>item.lane | undefined</td></tr><tr><td><code>item</code></td><td><code>data-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-virtualizer-sticky-bg</code></td><td><code>item</code></td><td><code>background</code></td><td><code>fixed</code></td><td><code>--xh-bg-surface</code></td><td>virtualizer 的 item 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-virtualizer-sticky-layer</code></td><td><code>item</code></td><td><code>z-index</code></td><td><code>fixed</code></td><td><code>--xh-layer-sticky</code></td><td>virtualizer 的 item 部件 z-index 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',52))])}const z=i(h,[["render",s]]);export{f as __pageData,z as default};
